insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_86_v1'
from (values
('127.685.d.1.A',3,'Two web designers in different cities build one site together by using:','["shared online tools such as cloud folders and video calls", "a landline only", "a typewriter", "postcards"]'::jsonb,0,'Online tools enable remote teamwork.','original'),
('127.685.d.1.A',4,'Local collaboration on a web project differs from online collaboration in that team members:','["never meet", "work in the same place", "use only email", "work on separate planets"]'::jsonb,1,'Local means in the same location.','original'),
('127.685.d.1.B',3,'A WYSIWYG web editor lets a designer:','["scan the page", "print the page", "build a page visually without writing every line of code", "fax the page"]'::jsonb,2,'WYSIWYG shows the result as you build.','original'),
('127.685.d.1.B',4,'Compared with a plain text editor, a web authoring program usually offers:','["only a printer", "no features", "only a blank page", "tools like previews, templates and code hints"]'::jsonb,3,'Authoring programs add helpful tools.','original'),
('127.685.d.1.C',3,'Checking whether a site works for visitors who use screen readers measures its:','["accessibility", "color", "price", "weight"]'::jsonb,0,'Accessibility covers assistive tech use.','original'),
('127.685.d.1.C',4,'A usability review finds that visitors cannot find the contact page. The designer should:','["ignore the finding", "make navigation clearer", "hide it further", "remove the menu"]'::jsonb,1,'Fix problems that users report.','original'),
('127.685.d.1.D',3,'Imagining a product that doesn''t exist yet but could grow from today''s trends is:','["filing", "copying old technology", "conceptualizing new technology", "recycling"]'::jsonb,2,'Concepts extend trends.','original'),
('127.685.d.1.D',4,'If many people now use mobile devices to browse, a designer might conceptualize:','["a site with no content", "a site for typewriters", "a site only for printers", "a site built mainly for phone use"]'::jsonb,3,'Trends shape new ideas.','original'),
('127.685.d.1.E',3,'A virtual classroom lets students attend class:','["over the internet from different places", "through the mail only", "only in person", "by radio only"]'::jsonb,0,'Virtual classes are online.','original'),
('127.685.d.1.E',4,'Distance learning is useful for a student who:','["has no internet and no devices", "lives far from the school", "does not own a device", "lives next door"]'::jsonb,1,'It removes travel barriers.','original'),
('127.685.d.1.F',3,'Windows, macOS and Linux each include tools for:','["painting", "knitting", "managing files and running web software", "baking"]'::jsonb,2,'Operating systems manage computing tasks.','original'),
('127.685.d.1.F',4,'A web designer testing a site should check it on more than one operating system because:','["the code changes by itself", "browsers never differ", "they all look identical", "pages can look different on different systems"]'::jsonb,3,'Cross-platform testing finds display issues.','original'),
('127.685.d.1.G',3,'When choosing software for a web team, a manager should consider the team''s needs and the software''s:','["cost and license", "icon", "slogan", "box art"]'::jsonb,0,'Cost and licensing are key factors.','original'),
('127.685.d.1.G',4,'Free open-source software can lower costs, but a team still must check its:','["box size", "license terms", "wallpaper", "logo"]'::jsonb,1,'Open source has license conditions.','original'),
('127.685.d.2.A',3,'Acceptable use of a company''s chat system means using it for:','["gossip", "harassment", "work communication in a professional way", "spam"]'::jsonb,2,'Professional use follows policy.','original'),
('127.685.d.2.A',4,'A policy on virtual communication may forbid:','["greeting coworkers", "scheduling meetings", "answering messages", "sharing confidential company information in public chats"]'::jsonb,3,'Confidentiality is protected.','original'),
('127.685.d.2.B',3,'Before sharing a file with a client, a web designer should ensure the file contains no:','["private or confidential data that should not be shared", "colors", "fonts", "images"]'::jsonb,0,'Check files before sending.','original'),
('127.685.d.2.B',4,'Sending a large file to many people is often done with a:','["fax", "cloud sharing link", "telegram", "paper copy"]'::jsonb,1,'Links are efficient for sharing.','original'),
('127.685.d.2.C',3,'A uniform resource locator should be shared only after you confirm it is:','["unknown", "encrypted by accident", "accurate and safe", "very long"]'::jsonb,2,'Check links before sharing.','original'),
('127.685.d.2.C',4,'A shortened link could hide a harmful destination, so you should:','["click it quickly", "post it publicly", "forward it", "preview where it leads before clicking"]'::jsonb,3,'Previewing prevents risk.','original'),
('127.685.d.2.D',3,'A web designer''s page won''t display correctly. A critical-thinking approach is to:','["test one possible cause at a time", "give up", "blame the browser first", "change everything at once"]'::jsonb,0,'Isolating variables finds the cause.','original'),
('127.685.d.2.D',4,'Comparing two possible fixes by their likely cost and effect is an example of:','["random choice", "evaluating options with evidence", "guessing", "avoiding the issue"]'::jsonb,1,'Evaluation supports decisions.','original'),
('127.685.d.2.E',3,'Which connection type usually offers steadier speeds for a desktop in a fixed spot?','["satellite only", "wireless", "wired", "none"]'::jsonb,2,'Wired links are less prone to interference.','original'),
('127.685.d.2.E',4,'A reason to choose wireless access in a classroom is that it:','["is always faster", "needs no router", "never fails", "lets devices move without cables"]'::jsonb,3,'Wireless adds mobility.','original'),
('127.685.d.3.A',3,'The currency of information on a web page refers to how:','["recent and up to date it is", "long it is", "colorful it is", "pretty it is"]'::jsonb,0,'Currency means timeliness.','original'),
('127.685.d.3.A',4,'A page about technology last updated ten years ago may be:','["perfectly current", "out of date", "brand new", "unreadable"]'::jsonb,1,'Old pages may be stale.','original'),
('127.685.d.3.B',3,'Typing OR between two words in a Boolean search tells the engine to return pages with:','["a random word", "both words only", "either word", "neither word"]'::jsonb,2,'OR broadens results.','original'),
('127.685.d.3.B',4,'To search for information on cats but exclude dogs, a researcher could type:','["dogs OR cats", "cats dogs dogs", "cats AND dogs", "cats NOT dogs"]'::jsonb,3,'NOT removes terms.','original'),
('127.685.d.3.C',3,'Knowing words like ''hyperlink'' and ''domain'' helps a web student:','["understand and discuss web topics", "skip class", "avoid reading", "ignore the web"]'::jsonb,0,'Vocabulary builds understanding.','original'),
('127.685.d.3.C',4,'The term ''bandwidth'' in web design refers to:','["page color", "how much data can move through a connection", "image shape", "font size"]'::jsonb,1,'Bandwidth measures capacity.','original'),
('127.685.d.3.D',3,'Crediting a source with an author, title and date is called:','["erasing", "deleting", "citing", "hiding"]'::jsonb,2,'Citing gives credit.','original'),
('127.685.d.3.D',4,'The reason to use an established citation method is to:','["hide the sources", "save paper", "delay reading", "let readers find your sources easily"]'::jsonb,3,'Consistent methods help readers.','original'),
('127.685.d.3.E',3,'An ethical way to get images for a website is to:','["use images you created or have license to use", "steal from a friend", "copy any image", "hack a photo site"]'::jsonb,0,'Ethical sourcing respects rights.','original'),
('127.685.d.3.E',4,'Following guidelines on acquiring digital content protects you from:','["good grades", "legal and ethical problems", "success", "new friends"]'::jsonb,1,'Guidelines prevent infringement.','original'),
('127.685.d.3.F',3,'A technology that learns patterns from data to make decisions is called:','["a monitor", "a cable", "artificial intelligence", "a keyboard"]'::jsonb,2,'AI learns from data.','original'),
('127.685.d.3.F',4,'One way smart assistants affect society is by:','["removing all jobs", "stopping the internet", "ending all work", "changing how people look up information"]'::jsonb,3,'They shift search habits.','original'),
('127.685.d.3.G',3,'The World Wide Web was developed by Tim Berners-Lee to:','["share documents using linked pages", "play games", "send telegrams", "print books"]'::jsonb,0,'The web links documents.','original'),
('127.685.d.3.G',4,'The internet and the World Wide Web are different because the web is:','["the same thing", "a service that runs on the internet", "a cable", "a computer"]'::jsonb,1,'The web uses the internet.','original'),
('127.685.d.3.H',3,'Proper grammar on a business website helps create:','["errors", "confusion", "a professional image", "doubt"]'::jsonb,2,'Quality writing builds trust.','original'),
('127.685.d.3.H',4,'A site with frequent spelling errors may cause visitors to:','["stay longer", "trust it more", "buy more", "doubt its quality"]'::jsonb,3,'Errors lower credibility.','original'),
('127.685.d.3.I',3,'The World Wide Web Consortium (W3C) is known for developing:','["web standards", "video games", "clothing lines", "phone plans"]'::jsonb,0,'W3C sets web standards.','original'),
('127.685.d.3.I',4,'Following web standards helps ensure that a site:','["breaks in every browser", "works across different browsers", "loads slower", "needs no testing"]'::jsonb,1,'Standards promote compatibility.','original'),
('127.685.d.3.J',3,'An interactive website lets visitors:','["only read text", "only look at photos", "do things like fill forms or play features", "only print"]'::jsonb,2,'Interactive sites respond to input.','original'),
('127.685.d.3.J',4,'An online quiz that gives instant scores is an example of:','["a brochure", "a printed map", "a static poster", "an interactive site feature"]'::jsonb,3,'It reacts to user input.','original'),
('127.685.d.3.K',3,'A dynamic website is one where content:','["changes based on data or user actions", "is hidden", "never changes", "is printed"]'::jsonb,0,'Dynamic pages update.','original'),
('127.685.d.3.K',4,'A small business with a few unchanging pages could use a:','["complex database", "static website", "game engine", "dynamic app"]'::jsonb,1,'Static sites fit simple needs.','original'),
('127.685.d.3.L',3,'Open source software is software whose code is:','["deleted", "encrypted", "available for others to view and modify", "secret"]'::jsonb,2,'Open source shares code.','original'),
('127.685.d.3.L',4,'Closed source software usually differs from open source in that its code is:','["posted online", "public domain", "free for all", "kept private by the owner"]'::jsonb,3,'Closed source is proprietary.','original'),
('127.685.d.3.M',3,'Search engines find pages by using programs called:','["crawlers or spiders", "speakers", "printers", "painters"]'::jsonb,0,'Crawlers index the web.','original'),
('127.685.d.3.M',4,'An advanced search option such as limiting results to a certain date range helps users:','["see more ads", "narrow results to what they need", "delete results", "slow the search"]'::jsonb,1,'Filters refine results.','original'),
('127.685.d.3.N',3,'A web storyboard is used to:','["print a page", "buy a domain", "plan the pages and how they link", "delete a site"]'::jsonb,2,'Storyboards map site structure.','original'),
('127.685.d.3.N',4,'Project management for a website includes setting:','["random guesses", "menus only", "unrelated games", "tasks, roles and deadlines"]'::jsonb,3,'Management organizes work.','original'),
('127.685.d.3.O',3,'A virtual private network (VPN) helps users by:','["creating a secure connection over the internet", "slowing the network", "cooling servers", "printing documents"]'::jsonb,0,'VPNs encrypt connections.','original'),
('127.685.d.3.O',4,'An employee working from a café might use a VPN to:','["bypass work", "protect company data on public Wi-Fi", "raise the volume", "play games"]'::jsonb,1,'VPNs secure traffic on open networks.','original'),
('127.685.d.3.P',3,'The protocol commonly used to transfer web pages to a browser is:','["FTP only", "POP only", "HTTP", "SMTP"]'::jsonb,2,'HTTP delivers web pages.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
